import sys

def crack_safe(numbers):
    operations = []

    while True:
        if all(n == 1 for n in numbers):
            break

        if any(n % 2 != 0 for n in numbers):
            # Find the first odd number and add 1 to it and its neighbor
            for i in range(4):
                if numbers[i] % 2 != 0:
                    numbers[i] += 1
                    numbers[(i + 1) % 4] += 1
                    operations.append(f"+{i + 1}")
                    break
        else:
            # Find the first even number and divide it and its neighbor by 2
            for i in range(4):
                if numbers[i] % 2 == 0:
                    numbers[i] //= 2
                    numbers[(i + 1) % 4] //= 2
                    operations.append(f"/{i + 1}")
                    break

    if len(operations) > 1000:
        return "-1"

    return "\n".join(operations)

